/**
 * Icon and colour maps for the Datastores page and drawer, keyed by the backend's codes.
 *
 * Every icon id is a full `'mdi:…'` string literal: the offline icon bundle is generated by scanning the
 * source for such literals (`scripts/generate-icon-bundle.mjs`), so an id assembled at runtime would be
 * missing from it. The maps approximate the Matters console's styling.
 */

import type { DatastoreRow } from '../../../types/dspmDatastores';

export interface Visual {
  icon: string;
  /** Text colour class for the icon. */
  cls: string;
}

export interface RiskVisual extends Visual {
  /** Classes of the tinted score box. */
  box: string;
}

const NEUTRAL = 'text-[rgba(0,0,0,0.4)]';

const RISK: Record<string, RiskVisual> = {
  CRITICAL: { icon: 'mdi:chevron-triple-up', cls: 'text-rose-600', box: 'border-rose-200 bg-rose-50 text-rose-700' },
  HIGH: { icon: 'mdi:chevron-double-up', cls: 'text-orange-500', box: 'border-orange-200 bg-orange-50 text-orange-700' },
  MEDIUM: { icon: 'mdi:equal', cls: 'text-amber-500', box: 'border-amber-200 bg-amber-50 text-amber-700' },
  LOW: { icon: 'mdi:chevron-double-down', cls: NEUTRAL, box: 'border-[rgba(0,0,0,0.1)] bg-[rgba(0,0,0,0.04)] text-[rgba(0,0,0,0.6)]' },
};

const RISK_FALLBACK: RiskVisual = {
  icon: 'mdi:circle-medium', cls: NEUTRAL, box: 'border-[rgba(0,0,0,0.1)] bg-[rgba(0,0,0,0.04)] text-[rgba(0,0,0,0.6)]',
};

/** Risk level (CRITICAL / HIGH / MEDIUM / LOW) to its chevron icon, colour and score-box tint. */
export const riskVisual = (level: string | null | undefined): RiskVisual => RISK[level ?? ''] ?? RISK_FALLBACK;

const SCAN_STATUS: Record<string, Visual> = {
  CLASSIFIED: { icon: 'mdi:check-circle', cls: 'text-emerald-500' },
  STOPPED: { icon: 'mdi:cancel', cls: 'text-rose-500' },
  NOT_SCANNED: { icon: 'mdi:rhombus-outline', cls: NEUTRAL },
  FAILED: { icon: 'mdi:alert-circle', cls: 'text-rose-500' },
  SCANNING: { icon: 'mdi:progress-clock', cls: 'text-sky-500' },
};

/** A datastore's scan status (list cell, filters). */
export const scanStatusVisual = (status: string | null | undefined): Visual =>
  SCAN_STATUS[status ?? ''] ?? { icon: 'mdi:circle-medium', cls: NEUTRAL };

const AGENT_STATUS: Record<string, Visual> = {
  ONLINE: { icon: 'mdi:check-circle', cls: 'text-emerald-500' },
  OFFLINE: { icon: 'mdi:close-circle', cls: 'text-rose-500' },
};

/** An endpoint agent's status: ONLINE green, OFFLINE red, anything else neutral. */
export const agentStatusVisual = (status: string | null | undefined): Visual =>
  AGENT_STATUS[status ?? ''] ?? { icon: 'mdi:circle-medium', cls: NEUTRAL };

/** A Scan History run's status. */
export const scanRunVisual = (status: string | null | undefined): Visual =>
  status === 'SCAN_STOPPED' ? { icon: 'mdi:circle-half-full', cls: NEUTRAL } : { icon: 'mdi:circle-medium', cls: NEUTRAL };

const FILE_TYPE_ICONS: Record<string, string> = {
  unknown_files: 'mdi:file-question-outline',
  xlsx_files: 'mdi:file-excel-outline',
  image_files: 'mdi:file-image-outline',
  pdf_files: 'mdi:file-pdf-box',
  documents: 'mdi:file-document-outline',
  web_markup: 'mdi:language-html5',
  compressed_files: 'mdi:folder-zip-outline',
  autocad: 'mdi:file-cad',
  code_files: 'mdi:file-code-outline',
  contact_files: 'mdi:card-account-details-outline',
  databases_files: 'mdi:database-outline',
  email: 'mdi:email-outline',
  log_files: 'mdi:text-box-outline',
  mailboxes: 'mdi:mailbox-outline',
  parquet_files: 'mdi:file-table-outline',
  presentations: 'mdi:file-powerpoint-outline',
  system_generated_files: 'mdi:file-cog-outline',
};

/** A file-type chip's icon (Information tab), by the overview's file-type key. */
export const fileTypeIcon = (key: string): string => FILE_TYPE_ICONS[key] ?? 'mdi:file-outline';

/**
 * Providers `DspmCloudMark` draws an AWS, GCP or Azure mark for. Mirrors the sets in `DspmIcons.tsx`,
 * which stays unchanged, so the Source / Account cell knows when to fall back to the provider icon.
 */
export const CLOUD_MARK_PROVIDERS: ReadonlySet<string> = new Set([
  'S3', 'EBS', 'RDS', 'RDS_ORACLE', 'DYNAMODB', 'DOCUMENTDB', 'MSK_KAFKA',
  'GCS', 'BIGQUERY', 'CLOUD_SQL',
  'AZURE_BLOB', 'AZURE_SQL', 'AZURE_SQL_SERVER',
]);

/**
 * The key `DspmProviderIcon` draws for a row's Datastore / Device cell: SaaS rows by drive type (a Gmail
 * mailbox or Google Drive), endpoint rows by OS (Apple, Windows), everything else by provider.
 */
export function datastoreIconKey(row: Pick<DatastoreRow, 'category' | 'subtype' | 'source'>): string | null {
  if (row.category === 'saas') {
    if (row.subtype === 'GMAIL') return 'GMAIL';
    if (row.subtype === 'GOOGLE_WORKSPACE') return 'GOOGLE_DRIVE';
    return row.source.provider;
  }
  if (row.category === 'endpoint') return row.subtype ?? row.source.provider;
  return row.source.provider;
}
